import{_ as a,C as i,o as n,c as r,E as o,a2 as d}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"稳定身份，不授权新的目的地","description":"","frontmatter":{"title":"稳定身份，不授权新的目的地","date":"2026-09-06","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"当持久智能体状态被恢复到重建或不同的目的地时，即使逻辑智能体或工作流身份保持稳定，系统仍必须重新验证什么？","summary":"稳定的逻辑身份能够把持久状态归给正确主体，却不能证明新工作空间兼容，也不能授予当前执行权限。安全恢复必须分别核验身份、状态连续性、目的地兼容性与现时权限。","sources":["research/analysis/Q-20260906-03-principal-identity-destination-authority.md"],"item_id":"Q-20260906-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-06-stable-identity-does-not-authorize-destination-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-06-stable-identity-does-not-authorize-destination.md","filePath":"zh/engineering/2026-09-06-stable-identity-does-not-authorize-destination.md","lastUpdated":1788754225000}'),s={name:"zh/engineering/2026-09-06-stable-identity-does-not-authorize-destination.md"};function l(p,e,h,c,u,b){const t=i("ArticleCover");return n(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-09-06-stable-identity-does-not-authorize-destination-editorial-v2.webp",kicker:"开源工程 · 每日研究",title:"稳定身份，不授权新的目的地",summary:"稳定的逻辑身份能够把持久状态归给正确主体，却不能证明新工作空间兼容，也不能授予当前执行权限。安全恢复必须分别核验身份、状态连续性、目的地兼容性与现时权限。",version:"Q-20260906-03",status:"Daily Runtime V5 · 2026-09-06",languageHref:"/en/engineering/2026-09-06-stable-identity-does-not-authorize-destination",languageLabel:"English"}),e[0]||(e[0]=d('<h1 id="稳定身份-不授权新的目的地" tabindex="-1">稳定身份，不授权新的目的地 <a class="header-anchor" href="#稳定身份-不授权新的目的地" aria-label="Permalink to &quot;稳定身份，不授权新的目的地&quot;">​</a></h1><p>持久状态被准确恢复到原来的逻辑智能体，校验和也全部匹配。系统于是允许它在另一个工作空间继续执行。问题是，正确归属只证明“这是谁的状态”，没有证明“这里允许它运行”，更没有证明“它现在可以做这些动作”。</p><p>本文的核心判断是：<strong>稳定主体身份支持可信的状态归属，却不授予目的地或执行权限。安全恢复必须分别证明主体身份、状态连续性、当前目的地兼容性和当前执行权限。</strong></p><h2 id="稳定身份解决归属-不解决许可" tabindex="-1">稳定身份解决归属，不解决许可 <a class="header-anchor" href="#稳定身份解决归属-不解决许可" aria-label="Permalink to &quot;稳定身份解决归属，不解决许可&quot;">​</a></h2><p>恢复过程至少面对两个相反错误。第一，名称重复、会话对象短暂或目标缺失时，系统可能把状态绑定给错误主体。第二，即使主体映射正确，目的地的信任、配置、指令、权限或当前工作状态可能已经变化。</p><p>把恢复视为一次反序列化，会把两类错误折叠成一个“加载成功”。更可靠的设计把“找到正确主体”视为必要条件，却不让它成为充分条件。</p><h2 id="两个实现展示了互补边界" tabindex="-1">两个实现展示了互补边界 <a class="header-anchor" href="#两个实现展示了互补边界" aria-label="Permalink to &quot;两个实现展示了互补边界&quot;">​</a></h2><p>同日研究对象比较了两个已合并的开源实现。</p><p>OpenAI Agents SDK（智能体软件开发工具包）的一项维护者提交，从智能体图派生稳定恢复身份，对同名智能体进行消歧，并避免把短暂的绑定会话对象提升为持久主体身份。在覆盖的身份感知恢复路径中，所需目标无法解析时会失败关闭，而不是悄悄选择方便的替代对象。</p><p>OpenAI Codex（开源编程智能体）的另一项维护者提交，处理托管工作树的恢复与所有权。它没有仅凭来源身份放行，而是重新检查来源与目的地的信任兼容性、目的地配置和状态、活动或排队中的排除条件、投射后的开发者指令、权限配置与会话事实。</p><p>第一个样本强化“状态属于谁”；第二个样本强化“此处现在是否接纳它”。两者来自同一组织维护的不同仓库，不构成独立厂商复现。它们支持的是覆盖路径中的工程模式，不是跨行业标准。</p><h2 id="四道门共同决定能否恢复" tabindex="-1">四道门共同决定能否恢复 <a class="header-anchor" href="#四道门共同决定能否恢复" aria-label="Permalink to &quot;四道门共同决定能否恢复&quot;">​</a></h2><p>受治理的恢复可以表达为四个可审计门禁：</p><table tabindex="0"><thead><tr><th>门禁</th><th>核心问题</th><th>失败示例</th></tr></thead><tbody><tr><td>主体身份</td><td>这份状态属于哪个逻辑智能体或工作流？</td><td>同名目标歧义、目标缺失</td></tr><tr><td>状态连续性</td><td>保存状态、谱系与可恢复上下文是否有效？</td><td>谱系断裂、版本不兼容</td></tr><tr><td>目的地兼容性</td><td>当前工作空间、会话或环境能否接纳它？</td><td>信任或配置不匹配</td></tr><tr><td>执行权限</td><td>该主体此刻在这里能做什么？</td><td>权限过期、范围变化、指令冲突</td></tr></tbody></table><p>只有四项同时成立，恢复才可进入执行。稳定身份可以让恢复具有确定性，但不会让它更宽松；可信目的地也不能修补错误主体或断裂状态。</p><p>失败结果应保留具体身份。“主体未解析”“状态不连续”“目的地不兼容”与“当前未授权”需要不同修复。若所有错误都返回“恢复失败”，运维人员可能通过增加重试掩盖真正的权限问题。</p><h2 id="工作空间、会话与派生都是重新准入点" tabindex="-1">工作空间、会话与派生都是重新准入点 <a class="header-anchor" href="#工作空间、会话与派生都是重新准入点" aria-label="Permalink to &quot;工作空间、会话与派生都是重新准入点&quot;">​</a></h2><p>目的地可能在持久状态休眠期间独立变化：仓库配置更新，信任级别改变，新的工作进入队列，权限被收窄，开发者指令覆盖范围改变，或原会话已被其他所有者接管。</p><p>因此，工作空间迁移、会话重建和智能体派生都应触发目的地敏感的重新准入。可以缓存不易变化的事实，但缓存必须绑定新鲜度规则。没有版本、时间或变化触发器的缓存，只是把过期权限藏进恢复路径。</p><p>派生尤其需要注意。子智能体可以继承任务背景或部分状态，却不应自动继承只授予父级的批准。状态连续性与权限连续性是不同命题。</p><h2 id="一个函数可以做完-证据不能混成一个字段" tabindex="-1">一个函数可以做完，证据不能混成一个字段 <a class="header-anchor" href="#一个函数可以做完-证据不能混成一个字段" aria-label="Permalink to &quot;一个函数可以做完，证据不能混成一个字段&quot;">​</a></h2><p>小型、单进程、完全受控的应用，可能合理地在一个恢复函数中完成四项检查。本文不要求四个微服务或四次网络调用；要求的是证据语义可以区分。</p><p>函数应至少返回可审计的决定理由，并记录检查时的主体、状态版本、目的地身份、配置和权限版本。界面可以只显示“可恢复”或“拒绝”，控制记录却必须回答哪道门失败，以及新信息出现后是否允许重试。</p><p>另一个成本反方意见是，每次迁移都重新检查太昂贵。风险比例化是合理做法：只读恢复与能够修改外部系统的恢复，可以使用不同门槛；但降低检查强度应是显式政策，而不是由成功加载状态暗中替代授权。</p><h2 id="对外部副作用保持单独谨慎" tabindex="-1">对外部副作用保持单独谨慎 <a class="header-anchor" href="#对外部副作用保持单独谨慎" aria-label="Permalink to &quot;对外部副作用保持单独谨慎&quot;">​</a></h2><p>四道门证明的是当前恢复准入，并不回答之前的外部动作是否恰好执行一次。状态保存之前发出的请求可能已经生效，也可能仍在网络中，或结果未知。</p><p>因此，外部效果身份、幂等键、对账与补偿证据应与状态恢复分开。成功重建内存状态，不能证明支付、部署、消息发送或远端写入的结果。对于结果未知的动作，系统需要先查询或对账，再决定继续、补偿还是停止。</p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>两个样本不能建立通用可移植智能体身份，也不能证明人类认证、法律授权、分布式恰好一次执行或所有恢复路径都被覆盖。稳定图身份本身也可能在拓扑变化后过期；目的地检查若缺少新鲜度，同样会失效。</p><p>开放问题包括：模型或智能体图变化后主体身份怎样延续；哪些目的地事实必须进入新鲜度身份；跨厂商运行系统如何交换谱系但不交换权限；派生或迁移时权限默认应怎样收窄；前次外部效果不明时，恢复协议需要什么证据。</p><p>最安全的工程规则很简单：把恢复当成一次重新准入。先证明状态属于谁，再证明状态连续、目的地兼容，并且这个主体现在有权在这里执行。</p><p><strong>证据与引用：</strong></p><ul><li><a href="https://github.com/openai/openai-agents-python/commit/4a11d20d126ebc844e362ae3abfe13b775dbaee3" target="_blank" rel="noreferrer">OpenAI Agents SDK 稳定图身份实现</a></li><li><a href="https://github.com/openai/codex/commit/f6976ab0369921a59e23416083587149807d8f93" target="_blank" rel="noreferrer">OpenAI Codex 托管工作树重新准入实现</a></li></ul>',33))])}const _=a(s,[["render",l]]);export{g as __pageData,_ as default};
